use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn swap_first_and_last(a: &mut Vec<i32>)
    requires
        a.len() > 0,  // Vector must be non-empty
    ensures
        // Length remains unchanged
        old(a).len() == a.len(),
        // First element becomes the original last element
        a[0] == old(a)[old(a).len() - 1],
        // Last element becomes the original first element  
        a[a.len() - 1] == old(a)[0],
        // All middle elements (if any) remain unchanged
        forall|i: int| 0 < i < old(a).len() - 1 ==> a[i] == old(a)[i],
{
    let old_len = a.len();
    
    // Extract the original values before swapping
    let first = a[0];
    let last = a[old_len - 1];
    
    // Perform the swap
    a[0] = last;
    a[old_len - 1] = first;
    
    // Verify postconditions
    proof {
        // Length remains unchanged
        assert(old(a).len() == a.len());
        
        // First element is now the original last
        assert(a[0] == old(a)[old_len - 1]);
        
        // Last element is now the original first
        assert(a[old_len - 1] == old(a)[0]);
        
        // All middle elements unchanged
        assert(forall|i: int| 0 < i < old_len - 1 ==> a[i] == old(a)[i]);
    }
}

}